import { test, expect, Page } from "@playwright/test";

import { loginAs } from "../support/auth";

async function readPrices(page: Page): Promise<number[]> {
  const texts = await page.locator('[data-test="inventory-item-price"]').allTextContents();
  return texts.map((text) => Number(text.replace("$", "")));
}

test.describe("TC-003: Sort products by price, low to high", () => {
  test("should sort products by price low to high", async ({ page }) => {
    await loginAs(page, "standard_user");

    const sortSelect = page.locator('[data-test="product-sort-container"]');
    await sortSelect.selectOption({ label: "Price (low to high)" });
    await expect(sortSelect).toHaveValue("lohi");
    await expect(sortSelect.locator("option:checked")).toHaveText("Price (low to high)");

    await expect(async () => {
      const prices = await readPrices(page);
      expect(prices.length).toBeGreaterThan(0);
      expect(prices).toEqual([...prices].sort((a, b) => a - b));
    }).toPass();

    const items = page.locator('[data-test="inventory-item"]');
    await expect(items.first().locator('[data-test="inventory-item-name"]')).toHaveText("Sauce Labs Onesie");
    await expect(items.first().locator('[data-test="inventory-item-price"]')).toHaveText("$7.99");
    await expect(items.last().locator('[data-test="inventory-item-name"]')).toHaveText("Sauce Labs Fleece Jacket");
    await expect(items.last().locator('[data-test="inventory-item-price"]')).toHaveText("$49.99");
  });
});
